return {["fb308_01"]={["down"]=[[fb308_03]],["dsc"]=[[这里是孙府后面的巷子，堆积着很多木箱杂物，平日很少有人往来。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_01]],["name"]=[[南巷]],["permission"]=1,["right"]=[[fb308_02]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_02"]={["down"]=[[fb308_11]],["dsc"]=[[这里是孙府北侧的小巷，连接着外面的大路。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_02]],["left"]=[[fb308_01]],["name"]=[[北巷]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_03"]={["down"]=[[fb308_05]],["dsc"]=[[这里是孙府后门，相对于前门而言这里显得有些荒凉，也并没有前门那般气派。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_03]],["name"]=[[后门]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb308_01]],["visible"]=1},["fb308_04"]={["dsc"]=[[这里是孙府的西厢房，是孙家大少爷的房间，房门口摆着很多盆栽，每一个看起来都非常雅致，价格不菲。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb308_04]],["name"]=[[西厢房]],["permission"]=1,["right"]=[[fb308_05]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_05"]={["down"]=[[fb308_09]],["dsc"]=[[这里是孙府后院，院内种着各异的花草树木，经人修剪后看起来很是漂亮，矮树丛中竖立着很多石头假山，有一种亲和自然的美感。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_05]],["left"]=[[fb308_04]],["name"]=[[后院]],["permission"]=1,["right"]=[[fb308_06]],["stepMusic"]=[[jiaobu]],["up"]=[[fb308_03]],["visible"]=1},["fb308_06"]={["dsc"]=[[这里是孙府的东厢房，是孙老爷和孙夫人的居所，里面陈设华丽，就连桌椅都是尚好的金丝楠木打造而成。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb308_06]],["left"]=[[fb308_05]],["name"]=[[东厢房]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_07"]={["dsc"]=[[这里是孙府的偏房，是曾经的孙家小姐居所，虽然屋内已经遍布灰尘，但从陈设来看昔日一定是一间典雅华丽的房间。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb308_07]],["name"]=[[偏房]],["permission"]=1,["right"]=[[fb308_08]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_08"]={["dsc"]=[[这里是孙府中的一处偏院被孙老爷改建成了一片池塘，池塘中荷花簇拥，水下锦鲤畅游，很是闲暇。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_08]],["left"]=[[fb308_07]],["name"]=[[池塘]],["permission"]=1,["right"]=[[fb308_09]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_09"]={["down"]=[[fb308_13]],["dsc"]=[[这里是孙府的正厅，是平日孙家人用餐会客之所，厅内除一张大的黄花梨八仙桌外还有很多紫檀木制成的家具，处处充满着古朴之美。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb308_09]],["left"]=[[fb308_08]],["name"]=[[正厅]],["permission"]=1,["right"]=[[fb308_10]],["stepMusic"]=[[jiaobu]],["up"]=[[fb308_05]],["visible"]=1},["fb308_10"]={["dsc"]=[[这里是孙府的书房，平日孙老爷最喜在此饮茶看书，若府中有贵客拜访，孙老爷也会将其请入书房共议要事。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb308_10]],["left"]=[[fb308_09]],["name"]=[[书房]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_11"]={["down"]=[[fb308_17]],["dsc"]=[[这里是孙府北侧的小巷，连接着外面的大路。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_11]],["name"]=[[北巷]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb308_02]],["visible"]=1},["fb308_12"]={["dsc"]=[[这里是孙府的下房，是孙府中丫鬟的居所。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb308_12]],["left"]=[[fb308_18]],["name"]=[[下房]],["permission"]=1,["right"]=[[fb308_13]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_13"]={["down"]=[[fb308_15]],["dsc"]=[[这里是孙府的前院，院中一扇诺达的影壁挡在门口，影壁上雕龙画虎，似有吓退来犯邪祟之威。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_13]],["left"]=[[fb308_12]],["name"]=[[前院]],["permission"]=1,["right"]=[[fb308_14]],["stepMusic"]=[[jiaobu]],["up"]=[[fb308_09]],["visible"]=1},["fb308_14"]={["dsc"]=[[这里是孙府的佛堂，佛堂中供奉着一尊玉观音，香案之上的青铜香炉早已被香灰填满，散落在台面之上。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb308_14]],["left"]=[[fb308_13]],["name"]=[[佛堂]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb308_15"]={["down"]=[[fb308_16]],["dsc"]=[[这里是孙府的大门，门上牌匾烫金纹样雕刻的孙府二字显得极为华贵，可见孙府宅主身份显赫，地位之高。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_15]],["name"]=[[孙府大门]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb308_13]],["visible"]=1},["fb308_16"]={["dsc"]=[[这里是孙府门前的南街，也是云镇主要的道路，平日来往行人马车居多，但近几日不知为何，来往行人都选择绕道而行。]],["enterfb203_ble"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb308_1